def compute(vars):
    expense_2018 = vars["v1"]
    expense_2019 = vars["v2"]
    higher_year = 2019 if expense_2019 > expense_2018 else 2018 if expense_2018 > expense_2019 else None
    return {
        "value": higher_year,
        "trace": {
            "expense_2018": expense_2018,
            "expense_2019": expense_2019,
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
